pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund the test contract to send ether
        vm.deal(address(this), 10 ether);
        // Warp to block where block.number % 15 == 0 (block 15) and timestamp > 0
        vm.roll(15);
        vm.warp(1);
        // First call: send 10 ether to reference (should succeed) or to buggy (should revert due to 9 ether require)
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // The reference accepts the call, then transfers all balance (10 ether) to msg.sender, leaving balance 0
        // The buggy contract reverts, so ok is false
        assertTrue(ok);
    }
}

