pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Force the block.number % 15 == 0 condition to be true
        vm.roll(15);
        // Set up an actor with 10 ether
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        // The reference reverts because msg.value != 10 ether, the modified version accepts 9 ether
        bool ok;
        try c.fallback{value: 9 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the call succeeded (this holds for the modified, but fails for the reference)
        assertTrue(ok);
        // After a success, the balance should be 9 ether (only the modified version gets here)
        assertEq(address(c).balance, 9 ether);
    }
}

