pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 30 ether);
        vm.warp(100);
        vm.roll(0);
        // First call: succeeds in both versions
        c.fallback{value: 10 ether}();
        // Warp to same timestamp (still 100), roll to block where block.number % 15 == 0
        vm.warp(100);
        vm.roll(15);
        // Second call: reference reverts (require block.timestamp > pastBlockTime fails), buggy version accepts
        bool success;
        try c.fallback{value: 10 ether}() {
            success = true;
        } catch {
            success = false;
        }
        // In reference, success = false; in buggy, success = true and balance transferred out => address(c).balance = 0
        // Assert that the reference behavior holds: the call should revert (success false)
        // For the buggy version, success will be true and assertTrue(!success) fails
        assertTrue(!success);
    }
}

