pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund contract with 10 ether
        vm.deal(address(c), 10 ether);
        // Set block.number to a multiple of 15 so fallback will transfer 10 ether
        vm.roll(15);
        uint ts = 1000;
        vm.warp(ts);

        // First call: succeeds
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        c.fallback{value: 10 ether}();

        // Now contract balance is 0 (all transferred out)
        // Attempt second call at the same timestamp
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        // In reference: require(block.timestamp > pastBlockTime) -> false -> revert
        // In buggy: require(block.timestamp >= pastBlockTime) -> true -> succeeds (but nothing to transfer)
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == false (revert)
        // Buggy: ok == true (no revert)
        assertTrue(!ok);
    }
}

