pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: two fallback calls at the same timestamp, block number set so first call triggers transfer
        vm.roll(15);          // block.number % 15 == 0, so first call will trigger transfer
        vm.warp(1000);        // Set initial timestamp
        vm.deal(address(this), 30 ether);
        // First call: succeeds in both versions
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        // Now the contract's pastBlockTime == 1000, balance = 10 ether - transferred to msg.sender? Actually transfer moves balance to msg.sender (this), so balance = 0 after transfer.
        // But we need to check divergence: second call at same timestamp
        vm.roll(16);          // block.number % 15 != 0, so no transfer
        // Second call at same timestamp 1000
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        // Reference: require(block.timestamp > pastBlockTime) -> false -> revert -> ok2 = false
        // Modified: require(block.timestamp >= pastBlockTime) -> true -> ok2 = true
        assertTrue(ok2);  // This will pass on modified (ok2=true) and fail on reference (ok2=false)
    }
}

