        c.fallback{value: 10 ether}();
        // Reference: balance should be 0 (first call transferred all 10 ether, second did nothing)
        // Buggy: first call did nothing (condition false), second call transferred all 10 ether, so balance is 10 ether
        assertEq(address(c).balance, 0 ether);
    }
}

